こういうことか
```interface Foo {
  foo: string;
}

interface Bar {
  bar: string;
}

function isFoo(arg: any): arg is Foo {
  return 'foo' in arg
}

const item1 = {foo: "foo"} as Foo | Bar;
const item2 = {foo: "bar"} as Foo | Bar;

function doSomething() {
  const item = item2
  if (isFoo(item)) {
    console.log(item.foo)
  } else {
    console.log(item.bar)
  }
}

doSomething()```

